        address[] memory initialRecipients = new address[](2);
        initialRecipients[0] = bob;
        initialRecipients[1] = charlie;

        uint256[] memory initialAmounts = new uint256[](2);
        initialAmounts[0] = 100;
        initialAmounts[1] = 100;

