        // Check balances - bob should be doubled due to reentrancy
        assertEq(ebu.getUserBalance(bob), 200, "Reentrancy: Bob's balance should be doubled");
        assertEq(ebu.getUserBalance(charlie), 100, "Charlie's balance should remain normal");
        assertEq(ebu.getUserBalance(attacker), 50, "Attacker should gain bonus balance");
    }
}

